&lt;/div&gt;
Ces objets sont des amulettes, des broches, des m&#233;daillons, des colliers, des charmes, des scarab&#233;es, des talismans et tous les objets port&#233;s autour du cou ou utilis&#233; pour fermer le col d’une cape ou d’un manteau. Les r&#232;gles relatives aux talismans sont d&#233;crites sur &lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html&quot; title=&quot;Les talismans&quot;&gt;cette page&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; autour du cou &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets.&lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0 g et 1 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s autour du cou&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#vents avantageux&quot; title=&quot;Les talismans&quot;&gt;Talisman de vents avantageux&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur fait une chute d’au moins 1,50m, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;50 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Vents Avantageux mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#convocations s&#233;curis&#233;es&quot; title=&quot;Les talismans&quot;&gt;Talisman de convocations s&#233;curis&#233;es&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur subit une attaque naturelle d’une cr&#233;ature convoqu&#233;e de l’alignement choisi &#224; la fabrication, conf&#232;re une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Mal.html&quot; title=&quot;Protection contre le Mal&quot;&gt;protection contre le Mal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Bien.html&quot; title=&quot;Protection contre le Bien&quot;&gt;le Bien&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Chaos.html&quot; title=&quot;Protection contre le Chaos&quot;&gt;le Chaos&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-La-Loi.html&quot; title=&quot;Protection contre la Loi&quot;&gt;la Loi&lt;/a&gt;&lt;/i&gt; selon cet alignement.&lt;/td&gt;&lt;td&gt;450 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Convocations S&#233;curis&#233;es mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#courage du guerrier&quot; title=&quot;Les talismans&quot;&gt;Talisman de courage du guerrier&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur doit &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Effray&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;effray&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Paniqu&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;paniqu&#233;&lt;/a&gt;, r&#233;duit cet &#233;tat &#224; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Secou&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;secou&#233;&lt;/a&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;450 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Courage du Guerrier mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#protection contre les projectiles&quot; title=&quot;Les talismans&quot;&gt;Talisman de protection contre les projectiles&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur subit 2 attaques &#224; distance ou plus lors d’un seul round, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-Projectiles.html&quot; title=&quot;Protection contre les projectiles&quot;&gt;protection contre les projectiles&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Protection Contre les Projectiles mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#sens du danger&quot; title=&quot;Les talismans&quot;&gt;Talisman de sens du danger&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur d&#233;termine son initiative, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anticipation-Du-Danger.html&quot; title=&quot;Anticipation du danger&quot;&gt;anticipation du danger&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Sens du Danger mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Main-Du-Mage.html&quot; title=&quot;Main du mage&quot;&gt;Main du mage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#libert&#233;&quot; title=&quot;Les talismans&quot;&gt;Talisman de libert&#233;&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur doit &#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Agripp&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;agripp&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Enchev&#234;tr&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;enchev&#234;tr&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Paralys&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;paralys&#233;&lt;/a&gt;, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Libert&#233;-De-Mouvement.html&quot; title=&quot;Libert&#233; de mouvement&quot;&gt;libert&#233; de mouvement&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Libert&#233; mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-Sanguinaire.html&quot; title=&quot;Collier sanguinaire&quot;&gt;Collier sanguinaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt; &#224; un animal &#224; 9m ou moins du porteur pendant 1 minute.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Collier-Sanguinaire.html&quot; title=&quot;Collier sanguinaire&quot;&gt;Collier Sanguinaire&lt;/a&gt; sup&#233;rieur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Collier Sanguinaire&lt;/i&gt;, mais conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croissance-Animale.html&quot; title=&quot;Croissance animale&quot;&gt;croissance animale&lt;/a&gt;&lt;/i&gt; pendant 1 minute (&#224; la place de ceux d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;| 14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Du-Scarab&#233;e-De-Sang.html&quot; title=&quot;Pendentif du scarab&#233;e de sang&quot;&gt;Pendentif du scarab&#233;e de sang&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MPNJ&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour et au prix d&#39;1d6 points de vie, permet de confirmer un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;critique potentiel&lt;/a&gt; automatiquement.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#protection contre les flammes&quot; title=&quot;Les talismans&quot;&gt;Talisman de protection contre les flammes&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur subit 5 points de d&#233;g&#226;ts ou plus d’un type d’&#233;nergie choisi &#224; la fabrication lors d’un seul round, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; contre ce type d’&#233;nergie avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;1 250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Protection Contre les Flammes mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 12 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-De-D&#233;fense.html&quot; title=&quot;Broche de d&#233;fense&quot;&gt;Broche de d&#233;fense&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Absorbe jusqu’&#224; 101 points de d&#233;g&#226;ts occasionn&#233;s par le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Projectile-Magique.html&quot; title=&quot;Projectile magique&quot;&gt;projectile magique&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Effigie-De-Gu&#233;rison.html&quot; title=&quot;Effigie de gu&#233;rison&quot;&gt;Effigie de gu&#233;rison&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 au premier &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; contre les effets continu. Lorsque les points de vie du porteur tombent en dessous de 0, soigne 2d8+3 points de vie avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Pare-Balle.html&quot; title=&quot;Amulette pare-balle&quot;&gt;Amulette pare-balle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance contre les armes &#224; feu qui visent la CA au contact.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 13 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 37 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Jet-De-Puanteur.html&quot; title=&quot;Amulette de jet de puanteur&quot;&gt;Amulette de jet de puanteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur dot&#233; de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Puanteur-(Capacit&#233;).html&quot; title=&quot;Puanteur (Ext)&quot;&gt;puanteur&lt;/a&gt; la perd et peut, une fois par heure, rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Fi&#233;vreux.html&quot; title=&quot;Fi&#233;vreux&quot;&gt;fi&#233;vreuses&lt;/a&gt; les cr&#233;atures dans un c&#244;ne de 9 m et soumettre cette m&#234;me zone &#224; un effet de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Graisse.html&quot; title=&quot;Graisse&quot;&gt;graisse&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;1 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-&#192;-Boules-De-Feu.html&quot; title=&quot;Collier &#224; boules de feu&quot;&gt;Collier &#224; boules de feu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;N’occupe pas d’emplacement. Permet de lancer plusieurs sph&#232;res (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt;) &#224; 21 m ou moins, infligeant un nombre diff&#233;rent de d6 selon le mod&#232;le du collier. Peut exploser s’il rate un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGRDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un effet de feu.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le I&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;2 sph&#232;res &#224; 3d6 et 1 sph&#232;re &#224; 5d6.&lt;/td&gt;&lt;td&gt;1 650 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le II&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;2 sph&#232;res &#224; 2d6, 2 sph&#232;res &#224; 4d6 et 1 sph&#232;re &#224; 6d6.&lt;/td&gt;&lt;td&gt;| 2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le III&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;4 sph&#232;res &#224; 3d6, 2 sph&#232;res &#224; 5d6 et 1 sph&#232;re &#224; 7d6.&lt;/td&gt;&lt;td&gt;| 4 350 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le IV&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;4 sph&#232;res &#224; 2d6, 2 sph&#232;res &#224; 4d6, 2 sph&#232;res &#224; 6d6 et 1 sph&#232;re &#224; 8d6.&lt;/td&gt;&lt;td&gt;| 5 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le V&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;2 sph&#232;res &#224; 3d6, 2 sph&#232;res &#224; 5d6, 2 sph&#232;res &#224; 7d6 et 1 sph&#232;re &#224; 9d6.&lt;/td&gt;&lt;td&gt;| 5 850 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le VI&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;4 sph&#232;res &#224; 4d6, 2 sph&#232;res &#224; 6d6, 2 sph&#232;res &#224; 8d6 et 1 sph&#232;re &#224; 10d6.&lt;/td&gt;&lt;td&gt;| 8 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mod&#232;le VII&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;2 sph&#232;res &#224; 3d6, 2 sph&#232;res &#224; 5d6, 2 sph&#232;res &#224; 7d6, 2 sph&#232;res &#224; 9d6 et 1 sph&#232;re &#224; 10d6.&lt;/td&gt;&lt;td&gt;| 8 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talisman-Purificateur.html&quot; title=&quot;Talisman purificateur&quot;&gt;Talisman purificateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre la maladie et le poison. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Purification-De-Nourriture-Et-Deau.html&quot; title=&quot;Purification de nourriture et d&amp;#39;eau&quot;&gt;purification de nourriture et d&#39;eau&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;1 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#chance&quot; title=&quot;Les talismans&quot;&gt;Talisman de chance&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur fait un 1 naturel en lancant un d20, permet relancer le d&#233; et conserver son second r&#233;sultat avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;1 680 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Chance mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 16 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Darmure-Naturelle.html&quot; title=&quot;Amulette d&amp;#39;armure naturelle&quot;&gt;Amulette d’armure naturelle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’alt&#233;ration &#224; l’armure naturelle.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 32 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-De-Cam&#233;l&#233;on-Racial.html&quot; title=&quot;Broche de cam&#233;l&#233;on racial&quot;&gt;Broche de cam&#233;l&#233;on racial&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer &#224; un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;demi-elfe&lt;/a&gt; un bonus de circonstances de +20 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt; pour para&#238;tre compl&#232;tement elfe ou compl&#232;tement humain.&lt;/td&gt;&lt;td&gt;2 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#puissance curative&quot; title=&quot;Les talismans&quot;&gt;Talisman de puissance curative&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le total de points de vie du porteur passe en dessous de la moiti&#233; de son total maximum, rend 4d8+7 points de vie avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;2 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Puissance Curative mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Araign&#233;e-Dairain.html&quot; title=&quot;Araign&#233;e d&amp;#39;airain&quot;&gt;Araign&#233;e d’airain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’utiliser la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;Sabotage.html&quot; title=&quot;Sabotage&quot;&gt;Sabotage&lt;/a&gt; &#224; 4,5 m sans malus. Peut &#234;tre utilis&#233;e comme &lt;a class=&quot;pagelink&quot; href=&quot;Outils-De-Cambrioleur-(Objet).html&quot; title=&quot;Outils de cambrioleur&quot;&gt;outil de cambrioleur de qualit&#233; sup&#233;rieure&lt;/a&gt; en permanence.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-Antigolems.html&quot; title=&quot;Broche antigolems&quot;&gt;Broche antigolems&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de d&#233;tecter les golems &#224; 18m ou moins &#224; volont&#233;. Les attaques &#224; mains nues, naturelles ou d’armes ignore la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; des golems.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ambre-De-Gaze.html&quot; title=&quot;Ambre de gaze&quot;&gt;Ambre de gaze&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Ghlaunder-(Technique).html&quot; title=&quot;Ghlaunder&quot;&gt;Ghlaunder&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-Grouillante.html&quot; title=&quot;Nu&#233;e grouillante&quot;&gt;nu&#233;e grouillante&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-Daraign&#233;es.html&quot; title=&quot;Araign&#233;e, Nu&#233;e d&amp;#39;araign&#233;es&quot;&gt;nu&#233;e d&#39;araign&#233;es&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREEVOLUEE&quot; title=&quot;Les arch&#233;types&quot;&gt;&#233;volu&#233;es&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-De-Moustiques.html&quot; title=&quot;Moustique, Nu&#233;e de moustiques&quot;&gt;nu&#233;e de moustiques&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREJEUNE&quot; title=&quot;Les arch&#233;types&quot;&gt;jeunes&lt;/a&gt;) une fois par jour.&lt;/td&gt;&lt;td&gt;2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-De-Gr&#226;ce-Du-H&#233;ros.html&quot; title=&quot;Pendentif de gr&#226;ce du h&#233;ros&quot;&gt;Pendentif de gr&#226;ce du h&#233;ros&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. Le porteur ne provoque pas d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaque d&#39;opportunit&#233;&lt;/a&gt; lorsqu&#39;il effectue un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Coupdegrace.html&quot; title=&quot;Coup de gr&#226;ce&quot;&gt;coup de gr&#226;ce&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-Tueuse-De-Nu&#233;es.html&quot; title=&quot;Broche tueuse de nu&#233;es&quot;&gt;Broche tueuse de nu&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les attaques &#224; mains nues, naturelles ou d’armes ignorent la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; des nu&#233;es. Immunise contre la capacit&#233; de distraction des nu&#233;es.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Porte-Bonheur.html&quot; title=&quot;Charme porte-bonheur&quot;&gt;Charme porte-bonheur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de relancer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;test de concentration&quot;&gt;concentration&lt;/a&gt; apr&#232;s avoir pris connaissance de son &#233;chec ou de sa r&#233;ussite.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pentacle-&#192;-Pointes-Dasmod&#233;us.html&quot; title=&quot;Pentacle &#224; pointes d&amp;#39;Asmod&#233;us&quot;&gt;Pentacle &#224; pointes d&#39;Asomd&#233;us&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de parade de +1&#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;. Un suivant d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Asmod&#233;us-(Technique).html&quot; title=&quot;Asmod&#233;us&quot;&gt;Asmod&#233;us&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt;&lt;/i&gt;, augmenter les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de ses sorts renforc&#233;s par l&#39;&#233;criture de 1, et utiliser cet objet comme &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Azlant.html&quot; title=&quot;Pendentif azlant&quot;&gt;Pendentif azlant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d&#39;une &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; choisie &#224; la fabrication. Un suivant d&#39;Aroden peut b&#233;n&#233;ficier d&#39;un bonus d&#39;intuition de +10 &#224; un test de comp&#233;tence qu&#39;il s&#39;appr&#234;te &#224; faire une fois par jour, et utiliser cet objet comme &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole sacr&#233;&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 100 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cristal-Blafard.html&quot; title=&quot;Cristal blafard&quot;&gt;Cristal blafard&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de boire l&#39;eau croupie et de manger la nourriture avari&#233;e comme si elles &#233;taient fra&#238;ches et saines. Un suivant d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Urgathoa-(Technique).html&quot; title=&quot;Urgathoa&quot;&gt;Urgathoa&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mise-&#192;-Mort.html&quot; title=&quot;Mise &#224; mort&quot;&gt;mise &#224; mort&lt;/a&gt;&lt;/i&gt; (sur une cr&#233;ature vivante ou morte-vivante) une fois par jour.&lt;/td&gt;&lt;td&gt;3 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Nocturne-De-Chagrin.html&quot; title=&quot;Pierre nocturne de chagrin&quot;&gt;Pierre nocturne de chagrin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +1 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; contre la terreur, et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; au feu 1. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Dahak-(Technique).html&quot; title=&quot;Dahak&quot;&gt;Dahak&lt;/a&gt; de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fracassement.html&quot; title=&quot;Fracassement&quot;&gt;fracassement&lt;/a&gt;&lt;/i&gt; une fois par jour, et &#234;tre rapidement identifi&#233; par les dragons.&lt;/td&gt;&lt;td&gt;3 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vurra-Du-Cr&#233;ateur.html&quot; title=&quot;Vurra du cr&#233;ateur&quot;&gt;Vurra du cr&#233;ateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (sculpture). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Magique.html&quot; title=&quot;Pierre magique&quot;&gt;pierre magique&lt;/a&gt;&lt;/i&gt; (fonctionne sur les rochers des g&#233;ants). Un suivant de Minderhal peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sagesse-Du-Hibou.html&quot; title=&quot;Sagesse du hibou&quot;&gt;sagesse du hibou&lt;/a&gt;&lt;/i&gt; une fois par jour.&lt;/td&gt;&lt;td&gt;3 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;daille-De-Cœur-H&#233;ro&#239;que.html&quot; title=&quot;M&#233;daille de cœur h&#233;ro&#239;que&quot;&gt;M&#233;daille de cœur h&#233;ro&#239;que&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de saintet&#233; de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; pour supprimer les &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt; temporaires. Le porteur peut d&#233;truire l&#39;objet pour &#233;viter de gagner 1 niveau n&#233;gatif permanent.&lt;/td&gt;&lt;td&gt;3 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collerette-Dimitateur.html&quot; title=&quot;Collerette d’imitateur&quot;&gt;Collerette d’imitateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +10 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; pour imiter les voix. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ventriloquie.html&quot; title=&quot;Ventriloquie&quot;&gt;ventriloquie&lt;/a&gt;&lt;/i&gt; pendant 5 minutes.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;daillon-De-Protection-Spirituelle.html&quot; title=&quot;M&#233;daillon de protection spirituelle&quot;&gt;M&#233;daillon de protection spirituelle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance +2 aux jets de sauvegarde contre les effets mentaux. Permet de relancer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGRDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; rat&#233; contre les sorts de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt;&lt;/i&gt; et de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Confusion.html&quot; title=&quot;Confusion&quot;&gt;confusion&lt;/a&gt;&lt;/i&gt;, si cette relance est r&#233;ussit, ce m&#233;daillon dispara&#238;t.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Talismans.html#souffle de vie&quot; title=&quot;Les talismans&quot;&gt;Talisman de souffle de vie&lt;/a&gt; mineur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur meurt, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souffle-De-Vie.html&quot; title=&quot;Souffle de vie&quot;&gt;souffle de vie&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; majeur&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme le &lt;i&gt;Talisman de Souffle de Vie mineur&lt;/i&gt;, mais peut conf&#233;rer ses avantages une fois par jour.&lt;/td&gt;&lt;td&gt;| 35 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Orbe-Du-Guide.html&quot; title=&quot;Orbe du guide&quot;&gt;Orbe du guide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt; (d&#233;g&#226;ts d&#39;&#233;lectricit&#233;). Un suivant d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Apsu-(Technique).html&quot; title=&quot;Apsu&quot;&gt;Apsu&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Splendeur-De-Laigle.html&quot; title=&quot;Splendeur de l&amp;#39;aigle&quot;&gt;splendeur de l&#39;aigle&lt;/a&gt;&lt;/i&gt; une fois par jour, et manifester les effets d&#39;un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;3 900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Conflit-&#201;l&#233;mentaire.html&quot; title=&quot;Amulette de conflit &#233;l&#233;mentaire&quot;&gt;Amulette de conflit &#233;l&#233;mentaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu’un ext&#233;rieur (&#233;l&#233;mentaire) est &#224; 18m ou moins, &#233;met la m&#234;me lumi&#232;re qu’une torche et conf&#232;re un r&#233;sistance de 5 contre un type d’&#233;nergie d&#233;pendant des ext&#233;rieurs d&#233;tect&#233;s contre les attaques de ces derniers. Les attaques ignorent la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; des ext&#233;rieurs d&#233;tect&#233;s.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Poings-Vertueux.html&quot; title=&quot;Amulette des poings vertueux&quot;&gt;Amulette des poings vertueux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’attaquer &#224; mains nues comme avec le don &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-&#192;-Mains-Nues.html&quot; title=&quot;Science du combat &#224; mains nues&quot;&gt;Science du combat &#224; mains nues&lt;/a&gt; pour utiliser des pouvoirs divins de repr&#233;sailles (&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ch&#226;timent-Sacr&#233;.html&quot; title=&quot;Ch&#226;timent sacr&#233;&quot;&gt;ch&#226;timent sacr&#233;&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du mal&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugement&lt;/a&gt; par exemple).&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Poings-Invincibles.html&quot; title=&quot;Amulette des poings invincibles&quot;&gt;Amulette des poings invincibles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;rent un bonus d’alt&#233;ration aux jets d’attaque et de d&#233;g&#226;ts et/ou une propri&#233;t&#233; sp&#233;ciale aux attaques &#224; mains nues et naturelles.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 36 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 64 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus maximal s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 100 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#233;pite-De-Shadgorum.html&quot; title=&quot;P&#233;pite de Shad&amp;#39;Gorum&quot;&gt;P&#233;pite de Shad&#39;Gorum&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +1 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; au feu 1. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Gorum-(Technique).html&quot; title=&quot;Gorum&quot;&gt;Gorum&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tal-Gel&#233;.html&quot; title=&quot;M&#233;tal gel&#233;&quot;&gt;m&#233;tal gel&#233;&lt;/a&gt;&lt;/i&gt; une fois par jour, et r&#233;parer des petits objets m&#233;talliques (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;paration.html&quot; title=&quot;R&#233;paration&quot;&gt;r&#233;paration&lt;/a&gt;&lt;/i&gt;) &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;4 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Stylet-Dard.html&quot; title=&quot;Stylet dard&quot;&gt;Stylet dard&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +3 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Son-Imaginaire.html&quot; title=&quot;Son imaginaire&quot;&gt;son imaginaire&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Calistria-(Technique).html&quot; title=&quot;Calistria&quot;&gt;Calistria&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ruse-Du-Renard.html&quot; title=&quot;Ruse du renard&quot;&gt;ruse du renard&lt;/a&gt;&lt;/i&gt; une fois par jour, et b&#233;n&#233;ficier d&#39;un bonus de +1 au premier &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d&#39;attaque&lt;/a&gt; sur une cr&#233;ature contre laquelle il a promis de se venger pendant 1 minute.&lt;/td&gt;&lt;td&gt;4 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-D&#233;fense-Instinctive.html&quot; title=&quot;Amulette de d&#233;fense instinctive&quot;&gt;Amulette de d&#233;fense instinctive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Si le porteur poss&#232;de l’&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ESQUIVEINSTINCTIVE&quot; title=&quot;Le roublard&quot;&gt;esquive instinctive&lt;/a&gt;, conf&#232;re l’&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ESQUIVEINSTINCTIVESUPERIEURE&quot; title=&quot;Le roublard&quot;&gt;esquive instinctive sup&#233;rieure&lt;/a&gt; (s’il la poss&#232;de d&#233;j&#224;, on consid&#232;re qu’il a 4 niveaux de classe en plus pour d&#233;terminer le nombre de niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; qu’il faut pour lui porter des &lt;a class=&quot;pagelink&quot; href=&quot;Roublard#Attaquesournoise.html&quot; title=&quot;attaque sournoise&quot;&gt;attaques sournoises&lt;/a&gt; en &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Priseentenaille.html&quot; title=&quot;prise en tenaille&quot;&gt;tenaille&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Du-Meilleur-Ami.html&quot; title=&quot;Pendentif du meilleur ami&quot;&gt;Pendentif du meilleur ami&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour et pendant un maximum de 48 heures, le porteur peut stocker un animal de taille P ou TP &#224; l&#39;int&#233;rieur.&lt;/td&gt;&lt;td&gt;5 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Du-Meilleur-Ami-Sup&#233;rieur.html&quot; title=&quot;Pendentif du meilleur ami sup&#233;rieur&quot;&gt;Pendentif du meilleur ami sup&#233;rieur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut &#233;galement stocker un animal de taille M ou G, un &#233;l&#233;mentaire, une cr&#233;ature magique ou un ext&#233;rieur de taille P ou TP.&lt;/td&gt;&lt;td&gt;| 9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Leurre-&#192;-Temp&#234;tes.html&quot; title=&quot;Leurre &#224; temp&#234;tes&quot;&gt;Leurre &#224; temp&#234;tes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer 50 % de chance d’&#233;checs aux attaques &#224; distance qui ciblent le porteur tout en permettant &#224; ce dernier d’infliger 4d6 points de d&#233;g&#226;ts d’&#233;lectricit&#233; aux cr&#233;atures adjacentes, pendant 1 minute.&lt;/td&gt;&lt;td&gt;5 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Talisman-De-D&#233;voration-Spirituelle.html&quot; title=&quot;Talisman de d&#233;voration spirituelle&quot;&gt;Talisman de d&#233;voration spirituelle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;BD&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Gemme-Spirituelle.html&quot; title=&quot;Cr&#233;ation de gemme spirituelle&quot;&gt;cr&#233;ation de gemme spirituelle&lt;/a&gt;&lt;/i&gt;. Le porteur peut ing&#233;rer la gemme cr&#233;&#233;e pour lib&#233;rer l&#39;&#226;me pi&#233;g&#233;e et obtenir une &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;Gu&#233;rison acc&#233;l&#233;r&#233;e (Ext)&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt; 2 pendant autant de rounds que le nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de l&#39;&#226;me lib&#233;r&#233;e.&lt;/td&gt;&lt;td&gt;5 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-De-Lenfant-F&#233;e.html&quot; title=&quot;Collier de l’enfant-f&#233;e&quot;&gt;Collier de l’enfant-f&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et de comp&#233;tences bas&#233;es sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; de +4 avec les gnomes, +2 avec les cr&#233;atures f&#233;eriques, et un malus de -2 face &#224; toutes les autres races. Le porteur obtient plusieurs traits raciaux des gnomes.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Torque-Du-Chant-Primal.html&quot; title=&quot;Torque du chant primal&quot;&gt;Torque du chant primal&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Quand le porteur effectue ou profite d’un &lt;a class=&quot;pagelink&quot; href=&quot;Scalde.html#CHANTEDRAGE&quot; title=&quot;Le scalde&quot;&gt;chant de rage&lt;/a&gt;, conf&#232;re les effets du don &lt;a class=&quot;pagelink&quot; href=&quot;Dur-&#192;-Cuire.html&quot; title=&quot;Dur &#224; cuire&quot;&gt;Dur &#224; cuire&lt;/a&gt; tant que le chant fait effet. Prolonge les effets des chants de rage et des &lt;a class=&quot;pagelink&quot; href=&quot;Barde#Representationbardique.html&quot; title=&quot;repr&#233;sentation bardique&quot;&gt;repr&#233;sentations bardiques&lt;/a&gt; favorables dont profite le porteur pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; apr&#232;s leur fin.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cha&#238;ne-De-D&#233;tention.html&quot; title=&quot;Cha&#238;ne de d&#233;tention&quot;&gt;Cha&#238;ne de d&#233;tention&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Enchev&#234;tr&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;enchev&#234;trer&lt;/a&gt; et emp&#234;cher de bouger une cr&#233;ature &#224; 4,50m ou moins, pendant 10 minutes maximum.&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-De-Bonne-Sant&#233;.html&quot; title=&quot;Charme de bonne sant&#233;&quot;&gt;Charme de bonne sant&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Immunise contre les maladies naturelles et surnaturelles.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Anti-Sommeil.html&quot; title=&quot;Amulette anti-sommeil&quot;&gt;Amulette anti-sommeil&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur peut faire des activit&#233;s simples pendant son temps de repos. Ce pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;puis&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;puise&lt;/a&gt; le porteur tous les 7 nuits d’utilisation pendant 1 journ&#233;e (ou 4 heures par nuit s’il retire l’amulette avant).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Protection-Contre-La-P&#233;trification.html&quot; title=&quot;Amulette de protection contre la p&#233;trification&quot;&gt;Amulette de protection contre la p&#233;trification&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;S’il rate un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; contre un effet de p&#233;trification, le porteur est seulement &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Chancelant&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;chancelant&lt;/a&gt; pendant 1d6 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; (ou 1 minute si l’effet n’autorisait pas de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Esprits.html&quot; title=&quot;Amulette des esprits&quot;&gt;Amulette des esprits&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Accorde des pouvoirs associ&#233;s &#224; un type d’&lt;a class=&quot;pagelink&quot; href=&quot;Esprits-(Chaman).html&quot; title=&quot;Les esprits du chaman&quot;&gt;esprit du chaman&lt;/a&gt; d&#233;pendant du mod&#232;le, mais rend le porteur vuln&#233;rable aux effets ciblant les cr&#233;atures li&#233;es &#224; ce type d’esprit. Si le porteur poss&#232;de d&#233;j&#224; le &lt;a class=&quot;pagelink&quot; href=&quot;Oracle.html#MYSTERE&quot; title=&quot;L&amp;#39;oracle&quot;&gt;myst&#232;re&lt;/a&gt; ou l’esprit associ&#233;, il n’obtient aucun nouveau pouvoir mais le niveau effectif des siens est augment&#233; de 2.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Cieux&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant qu’il voit un ciel nocturne en ext&#233;rieur, le porteur peut d&#233;terminer sa position et ajoute son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; &#224; tous ses tests de Charisme et de comp&#233;tence bas&#233;s sur le Charisme. Permet de forcer une cr&#233;ature &#224; consid&#233;rer le degr&#233; de luminosit&#233; dans lequel elle se trouve comme inf&#233;rieur de 2 niveaux (pendant 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Vent&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Du-Vent.html#Sceau_de_vent_Sur_2&quot; title=&quot;Esprit du Vent&quot;&gt;sceau de vent&lt;/a&gt; (20 % de chances de rater). Une fois par jour, permet d’infliger une &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Du-Vent.html#Aura_cr&#233;pitante_Sur_0&quot; title=&quot;Esprit du Vent&quot;&gt;aura cr&#233;pitante&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (5 points de d&#233;g&#226;ts, pendant 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Flammes&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Flammes.html#Sceau_de_flammes_Sur_4&quot; title=&quot;Esprit des Flammes&quot;&gt;sceau de flammes&lt;/a&gt; (1d6+4 points de d&#233;g&#226;ts, pendant 1 minute). Deux fois par jour, permet d’infliger une &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Flammes.html#Mal&#233;diction_de_feu_Sur_1&quot; title=&quot;Esprit des Flammes&quot;&gt;mal&#233;diction de feu&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (jusqu’&#224; la fin de son tour).&lt;/td&gt;&lt;td&gt;| 10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Pierres&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Pierres.html#Sceau_de_pierre_Sur_2&quot; title=&quot;Esprit des Pierres&quot;&gt;sceau de pierre&lt;/a&gt; (2 attaques, jusqu’&#224; 1 minute). Une fois par jour, permet d’infliger une &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Pierres.html#Mal&#233;diction_du_m&#233;tal_Sur_1&quot; title=&quot;Esprit des Pierres&quot;&gt;mal&#233;diction du m&#233;tal&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (malus de -4, pendant 2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Vagues&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Vagues.html#Linceul_de_brume_Sur_1&quot; title=&quot;Esprit des Vagues&quot;&gt;linceul de brume&lt;/a&gt; (2 attaques, jusqu’&#224; 1 minute). Une fois par jour, permet d’infliger un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Vagues.html#Appel_du_froid_Sur_0&quot; title=&quot;Esprit des Vagues&quot;&gt;appel du froid&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur.&lt;/td&gt;&lt;td&gt;| 10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Batailles&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Batailles.html#Sceau_martial_Sur_4&quot; title=&quot;Esprit des Batailles&quot;&gt;sceau martial&lt;/a&gt; (bonus de d&#233;part &#224; +3). Une fois par jour, permet d’infliger une &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Batailles.html#Mal&#233;diction_de_souffrance_Sur_1&quot; title=&quot;Esprit des Batailles&quot;&gt;mal&#233;diction de souffrance&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (pendant 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Os&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d’activer un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Os.html#Sceau_des_ossements_Sur_2&quot; title=&quot;Esprit des Os&quot;&gt;sceau des ossements&lt;/a&gt; (bonus de +2, pendant 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;). Une fois par jour, permet d’infliger un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Des-Os.html#Air_craintif_Sur_0&quot; title=&quot;Esprit des Os&quot;&gt;air craintif&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Effray&#233;.html&quot; title=&quot;Effray&#233;&quot;&gt;effray&#233;&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Vie&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur r&#233;cup&#232;re 1d6 ponts de vie suppl&#233;mentaire &#224; chaque fois qu’un sort de soin est lanc&#233; sur lui. Une fois par jour, permet d’infliger un &lt;a class=&quot;pagelink&quot; href=&quot;Esprit-De-La-Vie.html#Priver_de_secours_Sur_3&quot; title=&quot;Esprit de la Vie&quot;&gt;priver de secours&lt;/a&gt; &#224; une cr&#233;ature &#224; 9m ou moins du porteur (pendant 1 minute, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Main-Miraculeuse.html&quot; title=&quot;Main miraculeuse&quot;&gt;Main miraculeuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un emplacement d’anneau suppl&#233;mentaire. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re-Du-Jour.html&quot; title=&quot;Lumi&#232;re du jour&quot;&gt;lumi&#232;re du jour&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Garde-Tombes.html&quot; title=&quot;Pendentif garde-tombes&quot;&gt;Pendentif garde-tombes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Inflige un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; des morts-vivants qui visent le porteur (-4 pour les morts-vivants intangibles). Conf&#232;re un bonus de circonstance de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; des morts-vivants pour remarquer le porteur.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Torque-De-La-Furie-Du-Lion.html&quot; title=&quot;Torque de la furie du lion&quot;&gt;Torque de la furie du lion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de moral de +2 aux jets de sauvegarde contre les effets de terreur. Un &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; de niveau 12 ou plus obtient le pouvoir de rage &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#RAGESANSPEUR&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;rage sans peur&lt;/a&gt; (s’il le poss&#233;dait d&#233;j&#224;, il est immunis&#233; &#224; l’&#233;tat &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Paniqu&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;paniqu&#233;&lt;/a&gt; tant qu’il est enrag&#233;, et r&#233;cup&#232;re 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; chaque fois qu’il devrait subir cet &#233;tat).&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Torque-De-Rage-Sanglante.html&quot; title=&quot;Torque de rage sanglante&quot;&gt;Torque de rage sanglante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rage.html&quot; title=&quot;Rage&quot;&gt;rage&lt;/a&gt;&lt;/i&gt; au porteur pendant 6 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;, apr&#232;s quoi il est &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.-La-Fatigue-Se-Dissipe-Au-Bout-De-Huit-Heures-De-Repos-Total.-Un-Personnage-Fatigu&#233;-Devient-&#201;puis&#233;-D&#232;s-Qu’Il-Fait-Quoi-Que-Ce-Soit-Qui-Causerait-Un-Nouvel-&#201;tat-Fatigu&#233;..html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigu&#233;&lt;/a&gt; pendant 12 rounds. Une fois par jour, un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGE&quot; title=&quot;Le barbare&quot;&gt;rage&lt;/a&gt; peut s’en accorder 3 rounds suppl&#233;mentaires &#224; la place.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vestige-B&#233;ni.html&quot; title=&quot;Vestige b&#233;ni&quot;&gt;Vestige b&#233;ni&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Si un morceau d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt; avec un sous-type d&#39;alignement est stock&#233; dans l&#39;objet pendant 24 heures, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Bien.html&quot; title=&quot;D&#233;tection du Bien&quot;&gt;d&#233;tection du Bien&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Chaos.html&quot; title=&quot;D&#233;tection du Chaos&quot;&gt;Chaos&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Loi.html&quot; title=&quot;D&#233;tection de la Loi&quot;&gt;Loi&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;Mal&lt;/a&gt;&lt;/i&gt; (un appropri&#233;) &#224; volont&#233;, de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Bien.html&quot; title=&quot;Protection contre le Bien&quot;&gt;protection contre le Bien&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Chaos.html&quot; title=&quot;Protection contre le Chaos&quot;&gt;Chaos&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-La-Loi.html&quot; title=&quot;Protection contre la Loi&quot;&gt;Loi&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Le-Mal.html&quot; title=&quot;Protection contre le Mal&quot;&gt;Mal&lt;/a&gt;&lt;/i&gt; (un appropri&#233;) trois fois par jour, et de b&#233;n&#233;ficier de &lt;a class=&quot;pagelink&quot; href=&quot;Canalisation-Align&#233;e.html&quot; title=&quot;Canalisation align&#233;e&quot;&gt;Canalisation align&#233;e&lt;/a&gt; contre un sous-type d&#39;alignement appropri&#233;.&lt;/td&gt;&lt;td&gt;8 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Force-Soudaine.html&quot; title=&quot;Amulette de force soudaine&quot;&gt;Amulette de force soudaine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet soit d’effectuer une attaque au corps &#224; corps ou &#224; distance par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, soit de r&#233;cup&#233;rer 2 points de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;ki&lt;/a&gt; si le porteur en poss&#232;de une r&#233;serve.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Lumi&#232;re-Cach&#233;e.html&quot; title=&quot;Amulette de lumi&#232;re cach&#233;e&quot;&gt;Amulette de lumi&#232;re cach&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut &#233;mettre la m&#234;me lumi&#232;re qu’un &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-&#201;clairant-(Objet).html&quot; title=&quot;B&#226;ton &#233;clairant&quot;&gt;b&#226;ton &#233;clairant&lt;/a&gt; &#224; volont&#233;, sauf que les cr&#233;atures en dehors de la lumi&#232;re ne la voit pas.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Sombresire.html&quot; title=&quot;Amulette de sombresire&quot;&gt;Amulette de sombresire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’intuition de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; pour influencer les Ext&#233;rieurs Mauvais. Augmente la r&#233;sistance au froid, &#224; l’&#233;lectricit&#233; ou au feu d’un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;tieffelin&lt;/a&gt; de 5.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-En-Dent-De-Requin.html&quot; title=&quot;Amulette en dent de requin&quot;&gt;Amulette en dent de requin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet au porteur de se battre sous l’eau sans subir de malus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; ni aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;jets de d&#233;g&#226;ts&lt;/a&gt; (fonctionne &#233;galement avec les armes &#224; distance, mais impose un malus de -2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; et r&#233;duit leur &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Facteurdeportee.html&quot; title=&quot;facteur de port&#233;e&quot;&gt;facteur de port&#233;e&lt;/a&gt; de moiti&#233;).&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-Dadaptation.html&quot; title=&quot;Collier d&amp;#39;adaptation&quot;&gt;Collier d’adaptation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bulle-Dair.html&quot; title=&quot;Bulle d&amp;#39;air&quot;&gt;bulle d’air&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, immunisant contre les gaz/vapeurs toxiques et permettant de respirer dans l’eau et dans le vide.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;charpe-Des-Histoires-Glorieuses.html&quot; title=&quot;&#201;charpe des histoires glorieuses&quot;&gt;&#201;charpe des histoires glorieuses&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (danse). Conf&#232;re &#224; un porteur qui poss&#232;de un kapenia l&#233;gitime un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire) et lui permet de faire de tels tests sans formation.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Dastuce-Magique.html&quot; title=&quot;Amulette d&amp;#39;astuce magique&quot;&gt;Amulette d’astuce magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant qu’elle est l’&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;objet f&#233;tiche&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;, permet de pr&#233;parer 3 niveaux de sort suppl&#233;mentaire par jour.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-B&#233;n&#233;diction-Des-A&#238;n&#233;s.html&quot; title=&quot;Amulette de b&#233;n&#233;diction des A&#238;n&#233;s&quot;&gt;Amulette de b&#233;n&#233;diction des A&#238;n&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Gnome.html&quot; title=&quot;Les gnomes&quot;&gt;gnome&lt;/a&gt; n&#39;est pas consid&#233;r&#233; comme &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Extraplanaire.html&quot; title=&quot;Extraplanaire (sous-type)&quot;&gt;extraplanaire&lt;/a&gt; au Premier Monde. Soigne 1 point de d&#233;g&#226;t l&#233;tal et &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non-l&#233;taux&lt;/a&gt; toutes les minutes, jusqu&#39;&#224; un maximum quotidien &#233;gal au nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; du porteur. Conf&#232;re un bonus aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre l&#39;Affadissement.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Lignages.html&quot; title=&quot;Amulette des lignages&quot;&gt;Amulette des lignages&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Accorde des pouvoirs associ&#233;s &#224; un type de &lt;a class=&quot;pagelink&quot; href=&quot;Lignages.html&quot; title=&quot;Les lignages d&amp;#39;ensorceleur&quot;&gt;lignage d’ensorceleur&lt;/a&gt; d&#233;pendant du mod&#232;le, mais rend le porteur vuln&#233;rable aux effets ciblant les cr&#233;atures li&#233;es &#224; ce type de lignage. Si le porteur poss&#232;de d&#233;j&#224; le &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html#LIGNAGE&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;lignage&lt;/a&gt; associ&#233;, il n’obtient aucun nouveau pouvoir mais le niveau effectif des siens est augment&#233; de 2.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; F&#233;erique&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-F&#233;erique.html#Pouvoirs_de_lignage_2&quot; title=&quot;Lignage F&#233;erique&quot;&gt;regard furtif&lt;/a&gt; (jusqu’&#224; 9 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-F&#233;erique.html#Pouvoirs_de_lignage_2&quot; title=&quot;Lignage F&#233;erique&quot;&gt;toucher rieur&lt;/a&gt; (trois fois par jour).&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Vou&#233; &#224; un grand destin&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Vou&#233;-&#192;-Un-Grand-Destin.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Vou&#233; &#224; un grand destin&quot;&gt;destin&#233;&lt;/a&gt; (+2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; pendant les &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Roundsurprise.html&quot; title=&quot;round de surprise&quot;&gt;rounds de surprise&lt;/a&gt; et quand il ne voit pas venir une attaque) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Vou&#233;-&#192;-Un-Grand-Destin.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Vou&#233; &#224; un grand destin&quot;&gt;accomplissement de la proph&#233;tie&lt;/a&gt; (une fois par jour).&lt;/td&gt;&lt;td&gt;| 10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Abyssal&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Abyssal.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Abyssal&quot;&gt;r&#233;sistances d&#233;moniaques&lt;/a&gt; (r&#233;sistance de 5, +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre le poison) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Abyssal.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Abyssal&quot;&gt;griffes&lt;/a&gt; (1d4 points de d&#233;g&#226;ts).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; C&#233;leste&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-C&#233;leste.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage C&#233;leste&quot;&gt;r&#233;sistances c&#233;lestes&lt;/a&gt; (r&#233;sistances de 5) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-C&#233;leste.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage C&#233;leste&quot;&gt;feu c&#233;leste&lt;/a&gt; (trois fois par jour, 1d4+4 points de d&#233;g&#226;ts/soins).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Draconique&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Draconique.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Draconique&quot;&gt;r&#233;sistances draconiques&lt;/a&gt; (r&#233;sistance de 5, bonus d’amure naturelle de +1) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Draconique.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Draconique&quot;&gt;souffle&lt;/a&gt; (une fois par jour, 4d6 points de d&#233;g&#226;ts, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &#201;l&#233;mentaire&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-&#201;l&#233;mentaire.html#Pouvoirs_de_lignage_2&quot; title=&quot;Lignage &#201;l&#233;mentaire&quot;&gt;r&#233;sistances &#233;l&#233;mentaires&lt;/a&gt; (r&#233;sistance de 5) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-&#201;l&#233;mentaire.html#Pouvoirs_de_lignage_2&quot; title=&quot;Lignage &#201;l&#233;mentaire&quot;&gt;explosion &#233;l&#233;mentaire&lt;/a&gt; (une fois par jour, 4d6 points de d&#233;g&#226;ts).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Infernal&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Infernal.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Infernal&quot;&gt;r&#233;sistances infernales&lt;/a&gt; (r&#233;sistance de 5, +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre le poison) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Infernal.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Infernal&quot;&gt;toucher corrupteur&lt;/a&gt; (trois fois par jour, pendant 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Maudit&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Maudit.html#Pouvoirs_de_lignage_0&quot; title=&quot;Lignage Maudit&quot;&gt;mis&#233;rable endurance&lt;/a&gt; (+2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets de charme, de froid, de peur, de feu et de sommeil) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Maudit.html#Pouvoirs_de_lignage_0&quot; title=&quot;Lignage Maudit&quot;&gt;regard redout&#233;&lt;/a&gt; (trois fois par jour, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 18, pendant 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Mort-vivant&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Mort-Vivant.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Mort-vivant&quot;&gt;bienfait de la mort&lt;/a&gt; (r&#233;sistance de 5, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/- contre les d&#233;g&#226;ts &lt;a class=&quot;pagelink&quot; href=&quot;Blessures-Et-Mort.html#NONLETAL&quot; title=&quot;Blessures et mort&quot;&gt;non l&#233;taux&lt;/a&gt;) et de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Mort-Vivant.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Mort-vivant&quot;&gt;toucher du tombeau&lt;/a&gt; (trois fois par jour, moins de 8 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt;, pendant 4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;| 12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; Aberrant&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets de &lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Aberrant.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Aberrant&quot;&gt;long membres&lt;/a&gt; (1,50 m) et d’&lt;a class=&quot;pagelink&quot; href=&quot;Lignage-Aberrant.html#Pouvoirs_de_lignage_1&quot; title=&quot;Lignage Aberrant&quot;&gt;anatomie hors du commun&lt;/a&gt; (25 % de chances).&lt;/td&gt;&lt;td&gt;| 15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Poings-Glac&#233;s.html&quot; title=&quot;Amulette des poings glac&#233;s&quot;&gt;Amulette des poings glac&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Froid.html&quot; title=&quot;froid (propri&#233;t&#233;)&quot;&gt;de froid&lt;/a&gt; aux attaques &#224; mains nues et naturelles et leur donner les capacit&#233;s du &lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html#FERFROID&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;fer froid&lt;/a&gt;, &#224; volont&#233;. Tant que ces effets sont actifs, les mains du sujet sont fig&#233;es.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-Du-Fid&#232;le-Compagnon.html&quot; title=&quot;Collier du fid&#232;le compagnon&quot;&gt;Collier du fid&#232;le compagnon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re &#224; un animal d&#233;nu&#233; d’intelligence un bonus d’alt&#233;ration de +2 &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;, lui permettant de comprendre une langue choisie &#224; la fabrication. Au bout de 2 semaines de port, affecte un animal avec le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;veil.html&quot; title=&quot;&#201;veil&quot;&gt;&#233;veil&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre. Au bout d’une semaine, affecte un non-animal avec le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt;&lt;/i&gt; tant qu’il le porte.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;daillon-Des-Faux-Et-Vrais-Amis.html&quot; title=&quot;M&#233;daillon des faux et vrais amis&quot;&gt;M&#233;daillon des faux et vrais amis&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut d&#233;signer la derni&#232;re personne qui a menti au porteur et la derni&#232;re personne qui a agit en sa faveur. Conf&#232;re &#224; un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;demi-elfe&lt;/a&gt; un bonus &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;, aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; contre ses alli&#233;s, ceux qui pr&#233;tendent l&#39;&#234;tre et ceux qui l&#39;ont trahit r&#233;cemment.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pierres-&#192;-Message.html&quot; title=&quot;Pierres &#224; message&quot;&gt;Pierres &#224; message&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fabriqu&#233;es par paire, le porteur de l&#39;une peut communiquer avec le porteur de l&#39;autre tant qu&#39;elles sont &#224; moins de 5 km de distance.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-Dor&#233;.html&quot; title=&quot;Symbole sacr&#233; dor&#233;&quot;&gt;Symbole sacr&#233; dor&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu&#39;il sert de focalisateur divin pour un &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Divine.html&quot; title=&quot;La magie divine&quot;&gt;sort divin&lt;/a&gt;, rend au porteur un nombre de points de vie &#233;gal au niveau du sort lanc&#233;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; et dans la situation cit&#233;e, rend des points de vie au porteur et &#224; ses alli&#233;s pendant un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; &#233;gal au &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; de ce dernier.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Vie-Canalis&#233;e.html&quot; title=&quot;Amulette de vie canalis&#233;e&quot;&gt;Amulette de vie canalis&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu’il est la cible de soins prodigu&#233;s par de l’&#233;nergie positive, un porteur vivant avec le trait racial &lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html#AFFINITEAVECLENERGIENEGATIVE&quot; title=&quot;Les dhampirs&quot;&gt;affinit&#233; avec l’&#233;nergie n&#233;gative&lt;/a&gt; en r&#233;cup&#232;re tout de m&#234;me la moiti&#233; du montant sous forme de points de vie temporaires pendant 10 minutes.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-De-Protection-Contre-Les-Mal&#233;dictions.html&quot; title=&quot;Charme de protection contre les mal&#233;dictions&quot;&gt;Charme de protection contre les mal&#233;dictions&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de relancer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGRDE&quot; title=&quot;Valeurs de combat&quot;&gt;jet de sauvegarde&lt;/a&gt; (avant de conna&#238;tre son r&#233;sultat) contre une mal&#233;diction, et de conserver le r&#233;sultat de cette relance m&#234;me s’il est moins bon.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cristal-Des-Mains-Gu&#233;risseuses.html&quot; title=&quot;Cristal des mains gu&#233;risseuses&quot;&gt;Cristal des mains gu&#233;risseuses&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker les effets d’une &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#IMPOSITIONDESMAINS&quot; title=&quot;Le paladin&quot;&gt;imposition des mains&lt;/a&gt; dont le porteur peut b&#233;n&#233;ficier par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gorgerin-De-Protection.html&quot; title=&quot;Gorgerin de protection&quot;&gt;Gorgerin de protection&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’armure de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; (non cumulable avec un autre bonus d’armure) et la propri&#233;t&#233; de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;d&#233;fense l&#233;g&#232;re&lt;/a&gt;. Peut stocker les effets d’un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glyphe-De-Garde.html&quot; title=&quot;Glyphe de garde&quot;&gt;glyphe de garde&lt;/a&gt;&lt;/i&gt; dont le porteur peut b&#233;n&#233;ficier par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt; lorsqu’il est touch&#233; par une attaque au corps &#224; corps.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;daillon-Des-Pens&#233;es.html&quot; title=&quot;M&#233;daillon des pens&#233;es&quot;&gt;M&#233;daillon des pens&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Pens&#233;es.html&quot; title=&quot;d&#233;tection des pens&#233;es&quot;&gt;d&#233;tection des pens&#233;es&lt;/a&gt;&lt;/i&gt; en permanence.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pendentif-Dinsoumission.html&quot; title=&quot;Pendentif d&amp;#39;insoumission&quot;&gt;Pendentif d’insoumission&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet au porteur de s’infliger un &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissement temporaire&lt;/a&gt; de 2 &#224; ses valeurs de caract&#233;ristiques mentales pour effectuer une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Simple.html&quot; title=&quot;Action simple&quot;&gt;action simple&lt;/a&gt; alors qu’il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#H&#233;b&#233;t&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;h&#233;b&#233;t&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Naus&#233;eux&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;naus&#233;eux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Paralys&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;paralys&#233;&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#201;tourdi&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;tourdi&lt;/a&gt; par un effet mental. Immunise contre le sommeil provoqu&#233; par les effets mentaux.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Poings-Ardents.html&quot; title=&quot;Amulette des poings ardents&quot;&gt;Amulette des poings ardents&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer la propri&#233;t&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Feu.html&quot; title=&quot;feu (propri&#233;t&#233;)&quot;&gt;de feu&lt;/a&gt; aux attaques &#224; mains nues et naturelles et leur donner les capacit&#233;s de l’&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html#ADAMANTIUM&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;adamantium&lt;/a&gt;, &#224; volont&#233;. Tant que ces effets sont actifs, les mains du sujet sont fig&#233;es.&lt;/td&gt;&lt;td&gt;13 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-De-Bois-Vorace.html&quot; title=&quot;Broche de bois-vorace&quot;&gt;Broche de bois-vorace&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt; b&#233;n&#233;ficie des effets de &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#CAMOUFLAGE&quot; title=&quot;Le r&#244;deur&quot;&gt;camouflage&lt;/a&gt; du r&#244;deur tant qu’il &#233;volue en for&#234;t (s’il poss&#232;de un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#PACTEAVECLANATURE&quot; title=&quot;Le druide&quot;&gt;compagnon animal&lt;/a&gt; qui profite de son d&#233;placement facilit&#233;, ce dernier profite aussi du camouflage).&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Persuasion-Des-Morts-Vivants.html&quot; title=&quot;Amulette de persuasion des morts-vivants&quot;&gt;Amulette de persuasion des morts-vivants&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut produire de quoi nourrir un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;mort-vivant&lt;/a&gt; pendant 24 heures. Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Dhampir-(Race).html&quot; title=&quot;Les dhampirs&quot;&gt;dhampir&lt;/a&gt; est plus influent contre le mort-vivant affect&#233;. Une fois par jour, un porteur dhampir peut utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Mineur-Des-Morts-Vivants.html&quot; title=&quot;Contr&#244;le mineur des morts-vivants&quot;&gt;contr&#244;le mineur des morts-vivants&lt;/a&gt;&lt;/i&gt; une fois par jour sur le mort-vivant affect&#233;.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Abysses.html&quot; title=&quot;Amulette des Abysses&quot;&gt;Amulette des Abysses&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;BD&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme un &lt;a class=&quot;pagelink&quot; href=&quot;Symbole-Sacr&#233;-(Objet).html&quot; title=&quot;Symbole sacr&#233;&quot;&gt;symbole impie&lt;/a&gt; du seigneur d&#233;mon li&#233; &#224; l&#39;objet. Fonctionne comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phylact&#232;re-Du-Croyant.html&quot; title=&quot;Phylact&#232;re du croyant&quot;&gt;phylact&#232;re du croyant&lt;/a&gt;&lt;/i&gt; pour un suivant de ce dernier, et lui permet de lancer les trois &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Magiques-(Capacit&#233;).html&quot; title=&quot;Pouvoirs magiques (Mag)&quot;&gt;pouvoirs magiques&lt;/a&gt; offerts par la premi&#232;re faveur d&#39;exalt&#233; de ce serigneur d&#233;mon une fois par jour. Un porteur Bon ou Loyal acquiert 2 &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-De-Coagulation.html&quot; title=&quot;Charme de coagulation&quot;&gt;Charme de coagulation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Stabilise automatiquement le porteur lorsque son total de points de vie est n&#233;gatif. Double la gu&#233;rison naturelle. Immunise contre les effets de saignement qui n’inflige pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;affaiblissements temporaires&lt;/a&gt; ou permanents.&lt;/td&gt;&lt;td&gt;15 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-De-S&#233;r&#233;nit&#233;.html&quot; title=&quot;Collier de s&#233;r&#233;nit&#233;&quot;&gt;Collier de s&#233;r&#233;nit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur voit son niveau effectif augmenter de 4 pour d&#233;terminer sa &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;r&#233;serve de ki&lt;/a&gt; et les effets bas&#233;s sur les pouvoirs qui en d&#233;coulent.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;trangleur-Ophidien.html&quot; title=&quot;&#201;trangleur ophidien&quot;&gt;&#201;trangleur ophidien&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Enfil&#233; &#224; une cr&#233;ature &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Sansd&#233;fense.html&quot; title=&quot;Sans d&#233;fense&quot;&gt;sans d&#233;fense&lt;/a&gt;, une cr&#233;ature disposant du mot de commande peut imposer une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Qu&#234;te.html&quot; title=&quot;Qu&#234;te&quot;&gt;qu&#234;te&lt;/a&gt;&lt;/i&gt; au porteur, et soumet ce dernier &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suffocation.html&quot; title=&quot;Suffocation&quot;&gt;suffocation&lt;/a&gt;&lt;/i&gt; s&#39;il ne tente pas de l&#39;accomplir.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Broche-D&#233;tincelles-Ambr&#233;es.html&quot; title=&quot;Broche d’&#233;tincelles ambr&#233;es&quot;&gt;Broche d’&#233;tincelles ambr&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Chaque fois que le porteur subit des d&#233;g&#226;ts d’&#233;lectricit&#233;, en absorbe jusqu’&#224; 20 points (pour un maximum de 50 points stock&#233;s). Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;charge-&#201;lectrique.html&quot; title=&quot;D&#233;charge &#233;lectrique&quot;&gt;d&#233;charge &#233;lectrique&lt;/a&gt;&lt;/i&gt; (1d6 par tranche de 5 points stock&#233;s), &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;16 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Symbole-De-Protection-Sanguine.html&quot; title=&quot;Symbole de protection sanguine&quot;&gt;Symbole de protection sanguine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour apr&#232;s 24 heures de port, permet de s’infliger 1d6 points de d&#233;g&#226;ts pour cr&#233;er une dose d’&lt;a class=&quot;pagelink&quot; href=&quot;Eau-B&#233;nite-(Objet).html&quot; title=&quot;Eau b&#233;nite&quot;&gt;eau b&#233;nite&lt;/a&gt;. Les morts-vivants qui utilise &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-De-Sang-(Capacit&#233;).html&quot; title=&quot;Absorption de sang (Ext)&quot;&gt;absorption de sang&lt;/a&gt; sur le porteur subissent des d&#233;g&#226;ts et n’en tirent aucun avantage.&lt;/td&gt;&lt;td&gt;17 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corde-De-Potence.html&quot; title=&quot;Corde de potence&quot;&gt;Corde de potence&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsqu&#39;il est r&#233;duit &#224; 0 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt;, conf&#232;re au porteur une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 10/— et une &lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Acc&#233;l&#233;r&#233;e-(Capacit&#233;).html&quot; title=&quot;Gu&#233;rison acc&#233;l&#233;r&#233;e (Ext)&quot;&gt;gu&#233;rison acc&#233;l&#233;r&#233;e 5&lt;/a&gt; tant qu&#39;il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; (il appara&#238;t comme mort jusqu&#39;&#224; ce qu&#39;il reprenne conscience). Si une perte de point de vie devrait le tuer, le porteur peut d&#233;penser des utilisations de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour r&#233;cup&#233;rer 10 pv par utilisation d&#233;pens&#233;e.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Dopposition-Aux-Dragons.html&quot; title=&quot;Amulette d’opposition aux dragons&quot;&gt;Amulette d’opposition aux dragons&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Les attaques ignorent la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; des dragons. Permet de lancer 2 jets et de conserver le meilleur r&#233;sultat pour surpasser la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;RM&lt;/a&gt; des dragons. Un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; r&#233;ussit contre un souffle de dragon annule les d&#233;g&#226;ts de ce dernier.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Arts-Magiques.html&quot; title=&quot;Amulette des arts magiques&quot;&gt;Amulette des arts magiques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant qu’elle est l’&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;objet f&#233;tiche&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; universaliste, permet de choisir une &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#ECOLEDEMAGIE&quot; title=&quot;Le magicien&quot;&gt;&#233;cole de magie&lt;/a&gt; dont il pourra convertir ses sorts pr&#233;par&#233;s en d’autres sorts de cette &#233;cole.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ampoule-De-Sang-Factice.html&quot; title=&quot;Ampoule de sang factice&quot;&gt;Ampoule de sang factice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Apr&#232;s 24 heures de port, un porteur poss&#233;dant les pouvoirs d’un lignage d’ensorceleur les perds et gagnent ceux d’un autre lignage d’ensorceleur choisi &#224; la fabrication. Un m&#234;me porteur peut d&#233;truire l’ampoule pour &#233;changer son lignage d’ensorceleur avec celui de l’ampoule de fa&#231;on permanente.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-De-Contr&#244;le-Daluum.html&quot; title=&quot;Charme de contr&#244;le d’aluum&quot;&gt;Charme de contr&#244;le d&#39;aluum&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CCMI&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de contr&#244;ler un &lt;a class=&quot;pagelink&quot; href=&quot;Aluum.html&quot; title=&quot;Aluum&quot;&gt;aluum&lt;/a&gt; pr&#233;cis comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Personne.html&quot; title=&quot;Charme-personne&quot;&gt;charme-personne&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, et peut permettre de contr&#244;ler d&#39;autres aluum.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-De-Ma&#238;trise-Magique.html&quot; title=&quot;Amulette de ma&#238;trise magique&quot;&gt;Amulette de ma&#238;trise magique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant qu’elle est l’&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html#PACTEMAGIQUE&quot; title=&quot;Le magicien&quot;&gt;objet f&#233;tiche&lt;/a&gt; d’un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;, permet de pr&#233;parer 6 niveaux de sort suppl&#233;mentaire par jour.&lt;/td&gt;&lt;td&gt;22 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Main-De-Pierre.html&quot; title=&quot;Main de pierre&quot;&gt;Main de pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Vibrations-(Capacit&#233;).html&quot; title=&quot;Perception des vibrations (Ext)&quot;&gt;perception des vibrations&lt;/a&gt; (9m) sur les cr&#233;atures et les objets en contact avec la terre ou la pierre pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Charme-Antipoison.html&quot; title=&quot;Charme antipoison&quot;&gt;Charme antipoison&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Immunise contre les poisons (sauf ceux d&#233;j&#224; actifs avant le port).&lt;/td&gt;&lt;td&gt;27 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Dantid&#233;tection.html&quot; title=&quot;Amulette d&amp;#39;antid&#233;tection&quot;&gt;Amulette d’antid&#233;tection&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antid&#233;tection.html&quot; title=&quot;Antid&#233;tection&quot;&gt;antid&#233;tection&lt;/a&gt;&lt;/i&gt; (DD 19) en permanence.&lt;/td&gt;&lt;td&gt;35 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-Des-Frappes-Spectrales.html&quot; title=&quot;Collier des frappes spectrales&quot;&gt;Collier des frappes spectrales&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Sur un porteur intelligent (&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; 3+), conf&#232;re un bonus de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#DEGATS&quot; title=&quot;Valeurs de combat&quot;&gt;de d&#233;g&#226;ts&lt;/a&gt; ainsi que la propri&#233;t&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Spectrale.html&quot; title=&quot;spectrale (propri&#233;t&#233;)&quot;&gt;spectrale&lt;/a&gt;&lt;/i&gt; aux attaques &#224; mains nues. Au prix d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;point de ki&lt;/a&gt;, permet de porter une attaque &#224; mains nues par une attaque de &lt;a class=&quot;pagelink&quot; href=&quot;Intangible-(Capacit&#233;).html&quot; title=&quot;Intangible (Ext)&quot;&gt;contact intangible&lt;/a&gt;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, permet de devenir &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Intangible.html&quot; title=&quot;Intangible&quot;&gt;intangible&lt;/a&gt; pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;35 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scarab&#233;e-De-Protection.html&quot; title=&quot;Scarab&#233;e de protection&quot;&gt;Scarab&#233;e de protection&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance &#224; la magie (Ext)&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt; de 20. Peut absorber jusqu’&#224; 12 attaques de mort, capacit&#233;s li&#233;s &#224; l’&#233;nergie n&#233;gative ou effets similaires &#224; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;absorption d&amp;#39;&#233;nergie&quot;&gt;absorption d’&#233;nergie&lt;/a&gt;&lt;/i&gt; avant de dispara&#238;tre.&lt;/td&gt;&lt;td&gt;38 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-D&#233;toiles-Enchev&#234;tr&#233;es.html&quot; title=&quot;Collier d’&#233;toiles enchev&#234;tr&#233;es&quot;&gt;Collier d’&#233;toiles enchev&#234;tr&#233;es&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;res-Dansantes.html&quot; title=&quot;Lumi&#232;res dansantes&quot;&gt;lumi&#232;res dansantes&lt;/a&gt;&lt;/i&gt; &#224; volont&#233; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poussi&#232;re-D&#233;toile.html&quot; title=&quot;Poussi&#232;re d&amp;#39;&#233;toile&quot;&gt;poussi&#232;re d’&#233;toile&lt;/a&gt;&lt;/i&gt; une fois par jour. Sept fois par jour, permet de se rem&#233;morer un sort du niveau 0 ou 1 pr&#233;c&#233;demment lanc&#233;. Une fois par jour, permet de contrer un sort (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt;) avec un bonus de 12 + utilisations restantes du pouvoir pr&#233;c&#233;dent, si le contresort est une r&#233;ussite, permet d’utiliser le pouvoir pr&#233;c&#233;dent avec pour limite le niveau du sort contr&#233;. Ce dernier pouvoir &#233;puise toutes les utilisations restantes du pouvoir pr&#233;c&#233;dent et ne peut &#234;tre utilis&#233; s’il n’en reste d&#233;j&#224; plus.&lt;/td&gt;&lt;td&gt;42 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Collier-De-Fer-Du-Sabbat-D&#233;cha&#238;n&#233;.html&quot; title=&quot;Collier de fer du sabbat d&#233;cha&#238;n&#233;&quot;&gt;Collier de fer du sabbat d&#233;cha&#238;n&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; qui poss&#232;de le mal&#233;fice &lt;a class=&quot;pagelink&quot; href=&quot;Mal&#233;fices.html#Cercle&quot; title=&quot;Les mal&#233;fices de la sorci&#232;re&quot;&gt;cercle&lt;/a&gt; obtient trois pouvoirs la rapprochant des guenaudes.&lt;/td&gt;&lt;td&gt;46 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fermoir-Dagent.html&quot; title=&quot;Fermoir d&amp;#39;agent&quot;&gt;Fermoir d&#39;agent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fournis par paire associ&#233;e. Le fermoir d&#39;agent fournis les informations d&#39;un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rapport.html&quot; title=&quot;Rapport&quot;&gt;rapport&lt;/a&gt;&lt;/i&gt; constant au fermoir d&#39;administrateur. Les porteurs peuvent &lt;a class=&quot;pagelink&quot; href=&quot;Communication-&#192;-Distance.html&quot; title=&quot;Communication &#224; distance&quot;&gt;communiquer &#224; distance&lt;/a&gt; &#224; volont&#233;, le message &#233;tant stock&#233; dans le fermoir receveur s&#39;il n&#39;est pas port&#233; au moment de la communication.&lt;/td&gt;&lt;td&gt;60 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Torque-De-Langage-Universel.html&quot; title=&quot;Torque de langage universel&quot;&gt;Torque de langage universel&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur peut communiquer (comprendre et parler) &#224; toute cr&#233;ature parlant au moins une langue. Au &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade mythique&lt;/a&gt; 3 ce pouvoir s&#39;&#233;tant aux animaux, et au grade 6 il s&#39;&#233;tend aux plantes.&lt;/td&gt;&lt;td&gt;60 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#234;te-R&#233;duite.html&quot; title=&quot;T&#234;te r&#233;duite&quot;&gt;T&#234;te r&#233;duite&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;AO&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut &#234;tre tenu en main (n’occupant aucun emplacement). Une fois par jour, peut absorber un sort de niveau 5 ou moins qui cible le porteur. Pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; par niveau du sort absorb&#233;, peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;nergie-N&#233;gative.html&quot; title=&quot;&#201;nergie n&#233;gative&quot;&gt;&#233;nergie n&#233;gative&lt;/a&gt;&lt;/i&gt; (infligeant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;niveau n&#233;gatif&lt;/a&gt; par niveau du sort absorb&#233;). Peut &#234;tre utilis&#233;e comme focalisateur d’un sort de terreur pour augmenter son DD de 1.&lt;/td&gt;&lt;td&gt;90 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Amulette-Des-Plans.html&quot; title=&quot;Amulette des plans&quot;&gt;Amulette des plans&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changement-De-Plan.html&quot; title=&quot;Changement de plan&quot;&gt;changement de plan&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;, mais n&#233;cessite un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; DD 15 sinon, il y a 2 chances sur 5 pour qu’elle envoi les cibles sur un plan al&#233;atoire.&lt;/td&gt;&lt;td&gt;120 000 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
